mapper.select:
SELECT IFNULL(a.warning_num, 0) num
FROM vm_statistics_checkpoint_event_day a
WHERE `year` = YEAR(NOW())
AND `month` = MONTH(NOW())
AND `day` = DAY(NOW())
AND a.device_code = #{deviceCode}
AND a.device_code in

    #{item}

${dataScope}

SELECT a.alarm_id, a.alarm_type, a.alarm_time, a.province_name, a.province_code, a.city_name, a.city_code, a.county_code, a.county_name, a.longitude, a.latitude, a.alarm_body, a.channel_code, a.channel_name, a.device_code, a.device_name, a.pan, a.tilt, a.zoom, a.alarm_code, a.algorithm_code, a.alarm_video_url, a.original_picture_url, a.alarm_picture_url, a.create_time, a.delete_flag, a.importance_level, a.task_id, a.vehicle_number, a.vehicle_type, a.vehicle_num_color, a.vehicle_color FROM vm_checkpoint_warning_order_t a
AND a.delete_flag = 0 AND a.device_code in
#{item}
AND a.vehicle_number = #{vehicleNumber}
AND a.vehicle_number in
#{item}
AND a.device_code in
#{deviceCode}
AND a.device_name like CONCAT('%', #{deviceName}, '%')
AND a.channel_code in
#{channelCode}
AND (a.device_name like CONCAT('%', #{keywords}, '%') or a.vehicle_number like CONCAT('%', #{keywords}, '%'))
AND a.alarm_time >= #{queryStartTime} AND a.alarm_time <= #{queryEndTime}
${dataScope}
ORDER BY a.alarm_time DESC

SELECT sum(a.warning_num) num, a.month label FROM vm_statistics_checkpoint_event_month a WHERE `year` = YEAR(NOW()) AND a.device_code in
#{item}
${dataScope} GROUP BY a.month ORDER BY num DESC

SELECT cc.assigned_date AS label,IFNULL(SUM(t.today_all),0) AS num FROM( (SELECT distinct date_format(assigned_date,'%Y-%m') assigned_date FROM (SELECT adddate('2019-01-01',t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) assigned_date FROM (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3 ) c
and assigned_date between SUBSTR(#{queryStartTime},1,10) and SUBSTR(#{queryEndTime},1,10)
) cc LEFT JOIN (select date_format( a.create_date, '%Y-%m' ) as create_date,SUM(warning_num) as today_all from vm_statistics_checkpoint_event_day a
and a.create_date >= #{queryStartTime} and a.create_date <= #{queryEndTime}
AND a.device_code in
#{item}
${dataScope}
GROUP BY date_format( a.create_date, '%Y-%m' ) ) t ON t.create_date = cc.assigned_date) GROUP BY cc.assigned_date ORDER BY cc.assigned_date

SELECT sum(a.warning_num) num, a.day label FROM vm_statistics_checkpoint_event_day a WHERE `year` = YEAR(NOW()) AND `month` = MONTH(NOW()) AND a.device_code in
#{item}
${dataScope} GROUP BY a.day ORDER BY num DESC

SELECT cc.assigned_date AS label,IFNULL(SUM(t.today_all),0) AS num FROM( (SELECT date_format(assigned_date,'%Y-%m-%d') assigned_date FROM (SELECT adddate('2019-01-01',t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) assigned_date FROM (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3 ) c
and assigned_date between SUBSTR(#{queryStartTime},1,10) and SUBSTR(#{queryEndTime},1,10)
) cc LEFT JOIN (select date_format( a.create_date, '%Y-%m-%d' ) as create_date,SUM(warning_num) as today_all from vm_statistics_checkpoint_event_day a
and a.create_date >= #{queryStartTime} and a.create_date <= #{queryEndTime}
AND a.device_code in
#{item}
${dataScope}
GROUP BY date_format( a.create_date, '%Y-%m-%d' ) ) t ON date_format(t.create_date,'%Y-%m-%d') = cc.assigned_date) GROUP BY cc.assigned_date ORDER BY date_format(cc.assigned_date,'%Y-%m-%d')

SELECT t1.label,IFNULL(t2.num,0) AS num FROM ( SELECT 0 AS `hour`,'0:00-1:00' AS label UNION SELECT 1 AS `hour`,'1:00-2:00' AS label UNION SELECT 2 AS `hour`,'2:00-3:00' AS label UNION SELECT 3 AS `hour`,'3:00-4:00' AS label UNION SELECT 4 AS `hour`,'4:00-5:00' AS label UNION SELECT 5 AS `hour`,'5:00-6:00' AS label UNION SELECT 6 AS `hour`,'6:00-7:00' AS label UNION SELECT 7 AS `hour`,'7:00-8:00' AS label UNION SELECT 8 AS `hour`,'8:00-9:00' AS label UNION SELECT 9 AS `hour`,'9:00-10:00' AS label UNION SELECT 10 AS `hour`,'10:00-11:00' AS label UNION SELECT 11 AS `hour`,'11:00-12:00' AS label UNION SELECT 12 AS `hour`,'12:00-13:00' AS label UNION SELECT 13 AS `hour`,'13:00-14:00' AS label UNION SELECT 14 AS `hour`,'14:00-15:00' AS label UNION SELECT 15 AS `hour`,'15:00-16:00' AS label UNION SELECT 16 AS `hour`,'16:00-17:00' AS label UNION SELECT 17 AS `hour`,'17:00-18:00' AS label UNION SELECT 18 AS `hour`,'18:00-19:00' AS label UNION SELECT 19 AS `hour`,'19:00-20:00' AS label UNION SELECT 20 AS `hour`,'20:00-21:00' AS label UNION SELECT 21 AS `hour`,'21:00-22:00' AS label UNION SELECT 22 AS `hour`,'22:00-23:00' AS label UNION SELECT 23 AS `hour`,'23:00-24:00' AS label) t1 LEFT JOIN (SELECT warning_hour, SUM(warning_num) AS num FROM vm_statistics_checkpoint_event_hour a
AND a.device_code in
#{item}
AND a.create_date >= #{queryStartTime}
AND a.create_date <= #{queryEndTime}
${dataScope}
GROUP BY warning_hour ORDER BY warning_hour) t2 ON t1.`hour` = t2.warning_hour ORDER BY t1.`hour`

SELECT t1.label,IFNULL(t2.num,0) AS num FROM ( SELECT 0 AS `hour`,'0:00-1:00' AS label UNION SELECT 1 AS `hour`,'1:00-2:00' AS label UNION SELECT 2 AS `hour`,'2:00-3:00' AS label UNION SELECT 3 AS `hour`,'3:00-4:00' AS label UNION SELECT 4 AS `hour`,'4:00-5:00' AS label UNION SELECT 5 AS `hour`,'5:00-6:00' AS label UNION SELECT 6 AS `hour`,'6:00-7:00' AS label UNION SELECT 7 AS `hour`,'7:00-8:00' AS label UNION SELECT 8 AS `hour`,'8:00-9:00' AS label UNION SELECT 9 AS `hour`,'9:00-10:00' AS label UNION SELECT 10 AS `hour`,'10:00-11:00' AS label UNION SELECT 11 AS `hour`,'11:00-12:00' AS label UNION SELECT 12 AS `hour`,'12:00-13:00' AS label UNION SELECT 13 AS `hour`,'13:00-14:00' AS label UNION SELECT 14 AS `hour`,'14:00-15:00' AS label UNION SELECT 15 AS `hour`,'15:00-16:00' AS label UNION SELECT 16 AS `hour`,'16:00-17:00' AS label UNION SELECT 17 AS `hour`,'17:00-18:00' AS label UNION SELECT 18 AS `hour`,'18:00-19:00' AS label UNION SELECT 19 AS `hour`,'19:00-20:00' AS label UNION SELECT 20 AS `hour`,'20:00-21:00' AS label UNION SELECT 21 AS `hour`,'21:00-22:00' AS label UNION SELECT 22 AS `hour`,'22:00-23:00' AS label UNION SELECT 23 AS `hour`,'23:00-24:00' AS label) t1 LEFT JOIN (SELECT warning_hour, SUM(warning_num) AS num FROM vm_statistics_checkpoint_event_hour a
AND a.device_code in
#{item}
AND a.create_date >= #{queryStartTime}
AND a.create_date <= #{queryEndTime}
${dataScope}
GROUP BY warning_hour ORDER BY warning_hour) t2 ON t1.`hour` = t2.warning_hour ORDER BY t1.`hour`

SELECT a.device_code, a.device_name, a.warning_num num FROM vm_statistics_checkpoint_event_day a WHERE `year` = YEAR(NOW()) AND `month` = MONTH(NOW()) AND `day` = DAY(NOW()) AND a.device_code in
#{item}
${dataScope} ORDER BY num DESC

